from __future__ import annotations
from dataclasses import dataclass
from typing import Union

@dataclass(frozen=True)
class Affine:
    weights: tuple[float, ...]
    bias: float
@dataclass(frozen=True)
class Linear:
    weights: tuple[float, ...]
    children: tuple["Network", ...]
    bias: float
@dataclass(frozen=True)
class ReLU:
    child: "Network"
Network = Union[Affine, Linear, ReLU]

@dataclass(frozen=True)
class Pair:
    numerator: str
    denominator: str

def scale(c: float, pair: Pair) -> Pair:
    if c >= 0:
        return Pair(f"({c})*({pair.numerator})", f"({c})*({pair.denominator})")
    return Pair(f"({-c})*({pair.denominator})", f"({-c})*({pair.numerator})")

def compile_pair(node: Network) -> Pair:
    if isinstance(node, Affine):
        terms = [f"({a})*x{i}" for i, a in enumerate(node.weights)]
        return Pair(" + ".join(terms + [str(node.bias)]), "0")
    if isinstance(node, ReLU):
        pair = compile_pair(node.child)
        return Pair(f"max({pair.numerator}, {pair.denominator})", pair.denominator)
    pairs = [scale(w, compile_pair(child)) for w, child in zip(node.weights, node.children)]
    return Pair(" + ".join([p.numerator for p in pairs] + [str(node.bias)]),
                " + ".join([p.denominator for p in pairs] + ["0"]))

if __name__ == "__main__":
    net = Linear((2.0, -3.0),
                 (ReLU(Affine((1.0,), -1.0)), ReLU(Affine((-1.0,), -2.0))), 0.5)
    print(compile_pair(net))

